<?php
namespace App\Services;use App\Models\TransportService;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TransportServicePreparationService{public function __construct(private TransportSchedulingConflictService$conflicts,private TransportPassengerResolverService$resolver,private TransportAuditService$audit){}public function checklist(TransportService$s):array{$s->load(['route','vehicle','driver','monitor','passengers']);$conflicts=$this->conflicts->conflicts($s->company_id,$s->scheduled_start_at,$s->scheduled_arrival_at,$s->planned_vehicle_id,$s->planned_driver_id,$s->planned_monitor_id,$s->id);$count=$s->passengers->where('status','expected')->count();return['route_active'=>$s->route?->status==='active','vehicle_active'=>$s->vehicle?->status==='active','driver_active'=>$s->driver?->status==='active'&&$s->driver?->is_driver,'monitor_active'=>!$s->planned_monitor_id||($s->monitor?->status==='active'&&$s->monitor?->is_monitor),'conflicts'=>$conflicts,'passengers'=>$count,'capacity'=>$s->vehicle?->capacity??0,'capacity_ok'=>$s->vehicle&&$count<=$s->vehicle->capacity];}public function prepare(TransportService$s,int$user):void{if(!in_array($s->status,['draft','scheduled']))throw ValidationException::withMessages(['status'=>'Solo un servicio pendiente puede prepararse.']);if($s->passenger_snapshot_status!=='frozen')throw ValidationException::withMessages(['passengers'=>'Debe resolver, revisar y confirmar los pasajeros antes de preparar el servicio.']);$check=$this->checklist($s->fresh());$errors=[];foreach(['route_active'=>'La ruta no está activa.','vehicle_active'=>'Asigne un vehículo activo.','driver_active'=>'Asigne un conductor activo.','monitor_active'=>'El monitor asignado no está activo.','capacity_ok'=>'La cantidad de pasajeros supera la capacidad del vehículo.']as$key=>$message)if(!$check[$key])$errors[]=$message;if($check['conflicts'])$errors[]='Existen conflictos de '.implode(', ',$check['conflicts']).'.';if($errors)throw ValidationException::withMessages(['service'=>$errors]);DB::transaction(function()use($s,$user,$check){$s=TransportService::forCompany($s->company_id)->whereKey($s->id)->lockForUpdate()->firstOrFail();if(!in_array($s->status,['draft','scheduled'],true)||$s->passenger_snapshot_status!=='frozen')throw ValidationException::withMessages(['status'=>'El servicio cambió y ya no puede prepararse.']);$s->update(['status'=>'ready','updated_by'=>$user]);$this->audit->record($s->company_id,'transport_service_prepared','service',$s->id,$user,['passengers'=>$check['passengers']]);});}}
